def project(lon: float, lat: float) -> tuple[float, float]:
    """Longitude / latitude → SVG x, y in the map's viewBox."""
    return (round(_PAD + (lon - _LON0) * _K * _SCALE, 1), round(_PAD + (_LAT1 - lat) * _SCALE, 1))
